mapper.sql:
where 1=1

		and cdpv_llave = #{llaveTabla}


		and cdpv_estado = #{estado}


		and cdpv_documento = #{documento}


		and cdpv_producto = #{producto}


		and cdpv_productotercero = #{productoTercero}


		and cdpv_plantilla = #{plantilla}


		and cdpv_transaccionregistro = #{transaccionRegistro}


		and cdpv_transaccioninactivo = #{transaccionInactivo}


		and ((select upper(descripcion(cpro_documento)) from producto_prop where cpro_llave=cdpv_producto) like upper('%'||#{filtroParametro}||'%'))
